# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AKIŞKAN DİRENÇ KUVVETİ (Fd = K · A · v²) VE EN BÜYÜK KESİT ALANI (A)</text>\n  <rect x="20" y="45" width="320" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Direnç Kuvvetini Belirleyen Etkenler</text>\n  <text x="34" y="94" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Yönü:</tspan> Cismin hız vektörüne (v) daima zıt yöndedir.</text>\n  <text x="34" y="118" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">K (Direnç Katsayısı):</tspan> Akışkanın yoğunluğuna ve</text>\n  <text x="42" y="133" font-size="10" fill="#475569">cismin aerodinamik biçimine bağlıdır.</text>\n  <text x="34" y="156" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">A (Dik Kesit Alanı):</tspan> Hareket doğrultusuna dik</text>\n  <text x="42" y="171" font-size="10" fill="#475569">en geniş kesit alanı ile doğru orantılıdır.</text>\n  <rect x="36" y="184" width="288" height="40" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Matematiksel Model: Fd = K · A · v² (N)</text>\n\n  <rect x="360" y="45" width="320" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. Hareket Doğrultusuna Dik En Büyük Kesit</text>\n  <circle cx="440" cy="135" r="38" fill="#fde68a" stroke="#b45309" stroke-width="2"/>\n  <ellipse cx="440" cy="135" rx="38" ry="12" fill="#f59e0b" fill-opacity="0.35" stroke="#92400e" stroke-dasharray="4,3" stroke-width="1.8"/>\n  <line x1="440" y1="135" x2="478" y2="135" stroke="#991b1b" stroke-width="2"/>\n  <text x="459" y="130" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">r</text>\n  <text x="440" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Küre: A = π · r²</text>\n  <text x="440" y="208" text-anchor="middle" font-size="10" fill="#334155">(Ekvator Dairesi)</text>\n\n  <polygon points="595,95 555,165 635,165" fill="#fde68a" stroke="#b45309" stroke-width="2"/>\n  <ellipse cx="595" cy="165" rx="40" ry="11" fill="#f59e0b" fill-opacity="0.35" stroke="#92400e" stroke-width="1.8"/>\n  <line x1="595" y1="165" x2="635" y2="165" stroke="#991b1b" stroke-width="2"/>\n  <text x="615" y="160" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">2r</text>\n  <text x="595" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Koni (Taban: 2r): A = π · (2r)² = 4πr²</text>\n  <text x="595" y="208" text-anchor="middle" font-size="10" fill="#334155">(Taban Dairesi)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SERBEST DÜŞMEDEN LİMİT HIZA GEÇİŞ SÜRECİ (vL = kök(m·g / K·A))</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">1. Başlangıç Anı (t = 0)</text>\n  <circle cx="125" cy="112" r="18" fill="#38bdf8" stroke="#0369a1" stroke-width="2"/>\n  <line x1="125" y1="130" x2="125" y2="170" stroke="#dc2626" stroke-width="2.5"/>\n  <polygon points="120,168 130,168 125,178" fill="#dc2626"/>\n  <text x="148" y="160" font-size="10.5" font-weight="bold" fill="#dc2626">G = m·g</text>\n  <text x="35" y="196" font-size="10.5" fill="#334155">• v = 0  ⇒  Fd = 0</text>\n  <text x="35" y="212" font-size="10.5" fill="#334155">• Fnet = G = m·g</text>\n  <text x="35" y="228" font-size="10.5" font-weight="bold" fill="#0369a1">• İvme maksimumdur: a = g</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Hızlanma Süreci (v &lt; vL)</text>\n  <circle cx="350" cy="118" r="18" fill="#fbbf24" stroke="#b45309" stroke-width="2"/>\n  <line x1="350" y1="100" x2="350" y2="78" stroke="#2563eb" stroke-width="2.2"/>\n  <polygon points="345,80 355,80 350,71" fill="#2563eb"/>\n  <text x="372" y="88" font-size="10.5" font-weight="bold" fill="#2563eb">Fd</text>\n  <line x1="350" y1="136" x2="350" y2="174" stroke="#dc2626" stroke-width="2.5"/>\n  <polygon points="345,172 355,172 350,182" fill="#dc2626"/>\n  <text x="372" y="165" font-size="10.5" font-weight="bold" fill="#dc2626">G</text>\n  <text x="260" y="196" font-size="10.5" fill="#334155">• G &gt; Fd  ⇒  Fnet = G - Fd</text>\n  <text x="260" y="212" font-size="10.5" fill="#334155">• v artar, Fd artar, Fnet azalır</text>\n  <text x="260" y="228" font-size="10.5" font-weight="bold" fill="#b45309">• Azalan ivmeyle hızlanır</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Limit Hız Durumu (v = vL)</text>\n  <circle cx="575" cy="122" r="18" fill="#4ade80" stroke="#15803d" stroke-width="2"/>\n  <line x1="575" y1="104" x2="575" y2="72" stroke="#2563eb" stroke-width="2.5"/>\n  <polygon points="570,74 580,74 575,64" fill="#2563eb"/>\n  <text x="602" y="86" font-size="10.5" font-weight="bold" fill="#2563eb">Fd = G</text>\n  <line x1="575" y1="140" x2="575" y2="174" stroke="#dc2626" stroke-width="2.5"/>\n  <polygon points="570,172 580,172 575,182" fill="#dc2626"/>\n  <text x="598" y="165" font-size="10.5" font-weight="bold" fill="#dc2626">G</text>\n  <text x="485" y="196" font-size="10.5" fill="#334155">• Fd = G  ⇒  Fnet = 0, a = 0</text>\n  <text x="485" y="212" font-size="10.5" fill="#334155">• Cisim sabit vL hızıyla düşer</text>\n  <text x="485" y="228" font-size="10.5" font-weight="bold" fill="#15803d">• vL = kök(m·g / (K·A))</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HAVA ORTAMINDA DÜŞEY HAREKETİN HIZ-ZAMAN VE İVME-ZAMAN GRAFİKLERİ</text>\n  <rect x="20" y="45" width="320" height="192" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Hız – Zaman Grafiği (v - t)</text>\n  <line x1="60" y1="205" x2="310" y2="205" stroke="#334155" stroke-width="2"/>\n  <line x1="60" y1="215" x2="60" y2="75" stroke="#334155" stroke-width="2"/>\n  <line x1="60" y1="145" x2="305" y2="145" stroke="#dc2626" stroke-dasharray="5,4" stroke-width="1.8"/>\n  <text x="42" y="149" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">vL</text>\n  <path d="M 60 205 Q 115 147 220 145 L 300 145" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <text x="165" y="182" font-size="10" font-weight="bold" fill="#15803d">v0 = 0 (Serbest düşme:</text>\n  <text x="165" y="195" font-size="10" fill="#15803d">Azalan ivmeyle hızlanır)</text>\n  <path d="M 60 90 Q 115 143 220 145 L 300 145" fill="none" stroke="#7c3aed" stroke-width="2.5"/>\n  <text x="42" y="94" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">v0</text>\n  <text x="180" y="102" font-size="10" font-weight="bold" fill="#6d28d9">v0 &gt; vL (Hızlı atılan:</text>\n  <text x="180" y="115" font-size="10" fill="#6d28d9">Azalan ivmeyle yavaşlar)</text>\n  <text x="315" y="209" font-size="11" font-weight="bold" fill="#334155">t</text>\n\n  <rect x="360" y="45" width="320" height="192" rx="10" fill="#ffffff" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Serbest Düşmede İvme – Zaman (a - t)</text>\n  <line x1="400" y1="195" x2="650" y2="195" stroke="#334155" stroke-width="2"/>\n  <line x1="400" y1="210" x2="400" y2="75" stroke="#334155" stroke-width="2"/>\n  <text x="385" y="95" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">g</text>\n  <text x="385" y="199" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">0</text>\n  <path d="M 400 92 Q 455 192 560 195 L 645 195" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <line x1="560" y1="190" x2="560" y2="202" stroke="#334155" stroke-width="1.5"/>\n  <text x="560" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#334155">tL (Limit Hız Anı)</text>\n  <text x="535" y="120" font-size="10.5" font-weight="bold" fill="#991b1b">• t = 0 anında a = g</text>\n  <text x="535" y="140" font-size="10.5" fill="#334155">• Hız arttıkça Fd artar,</text>\n  <text x="543" y="155" font-size="10.5" fill="#334155">net kuvvet ve ivme azalır.</text>\n  <text x="535" y="175" font-size="10.5" font-weight="bold" fill="#15803d">• t ≥ tL için a = 0 olur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
